+import { SecretsManagerClient, GetSecretValueCommand } from "@aws-sdk/client-secrets-manager";
+
+const secrets = new SecretsManagerClient({});
+const GATEWAY_URL = process.env.GATEWAY_URL ?? "";
+const SETUP_TOKEN_SECRET = process.env.SETUP_TOKEN_SECRET ?? "";
+
+type Event = { requestContext?: { authorizer?: { iam?: { userArn?: string } } } };
+
+const response = (statusCode: number, body: unknown) => ({
+  statusCode,
+  headers: { "content-type": "application/json" },
+  body: JSON.stringify(body),
+});
+
+/**
+ * Mint the caller's virtual key.
+ *
+ * The Function URL is `AWS_IAM`, so AWS has already verified the caller's
+ * signature, and the ARN in the event is the identity the key belongs to. The
+ * request body is never parsed, so a caller cannot ask for someone else's key.
+ * The setup token is read on each invocation so a rotation needs no redeploy,
+ * and neither the token nor the key is logged.
+ */
+export const handler = async (event: Event) => {
+  if (!GATEWAY_URL || !SETUP_TOKEN_SECRET) return response(503, { message: "not configured" });
+  const email = event.requestContext?.authorizer?.iam?.userArn?.split("/").pop() ?? "";
+  if (!email.includes("@")) return response(403, { message: "no caller identity" });
+  const secret = await secrets.send(new GetSecretValueCommand({ SecretId: SETUP_TOKEN_SECRET }));
+  if (!secret.SecretString) return response(503, { message: "setup token unavailable" });
+  const res = await fetch(`${GATEWAY_URL}/api/governance/virtual-keys`, {
+    method: "POST",
+    headers: { "content-type": "application/json", "x-bifrost-setup-token": secret.SecretString },
+    body: JSON.stringify({ name: email }),
+  });
+  return { statusCode: res.status, headers: { "content-type": "application/json" }, body: await res.text() };
+};
