+import * as pulumi from "@pulumi/pulumi";
+import * as aws from "@pulumi/aws";
+import type { createWorkbenchNetwork } from "./network";
+
+type WorkbenchNetwork = ReturnType<typeof createWorkbenchNetwork>;
+
+export type GatewayDiscovery = {
+  namespace: aws.servicediscovery.PrivateDnsNamespace;
+  service: aws.servicediscovery.Service;
+  endpoint: pulumi.Output<string>;
+};
+
+/**
+ * A private name for the gateway task.
+ *
+ * Step 2 of `docs/example-mint-function.md` has the mint function call the
+ * gateway task on 8080 directly. A Fargate task has no address that survives a
+ * redeploy, so the function needs a name that does: a Cloud Map namespace
+ * private to the VPC the task already runs in, and the service `ecs.ts`
+ * registers the task into. Nothing public is created and no DNS record is
+ * written by hand.
+ */
+export const createGatewayDiscovery = (args: {
+  provider: aws.Provider;
+  network: WorkbenchNetwork;
+}): GatewayDiscovery => {
+  const { provider, network } = args;
+
+  const namespace = new aws.servicediscovery.PrivateDnsNamespace(
+    "bifrostNamespace",
+    {
+      name: "workbench.local",
+      description: "Private names for the workbench account.",
+      vpc: network.vpc.id,
+    },
+    { provider },
+  );
+
+  const service = new aws.servicediscovery.Service(
+    "bifrostTask",
+    {
+      name: "bifrost",
+      dnsConfig: {
+        namespaceId: namespace.id,
+        dnsRecords: [{ ttl: 10, type: "A" }],
+      },
+      healthCheckCustomConfig: { failureThreshold: 1 },
+    },
+    { provider },
+  );
+
+  return {
+    namespace,
+    service,
+    endpoint: pulumi.interpolate`http://${service.name}.${namespace.name}:8080`,
+  };
+};
